"use client"

import React from "react"
import {
    useTranslations,
} from "next-intl"
import { Button } from "@/components/atoms/buttons/Button"
import { StackV } from "@/components/frames/Stack"
import type {
    OauthButtonItem,
} from "../map"
import type { KeycloakIdentityProvider } from "@/modules/api/graphql/mutations/types/exchange-code-for-token"

/** Props for {@link OauthButtons}. */
export interface OauthButtonsProps {
    /** OAuth provider buttons to render, in display order. */
    items: Array<OauthButtonItem>
    /** Fired with the chosen provider when a button is pressed. */
    onOauthPress: (provider: KeycloakIdentityProvider) => void
}

/**
 * Vertical stack of OAuth shortcut buttons (Google, GitHub, …).
 *
 * Presentational: maps {@link OauthButtonItem}s to buttons and forwards the
 * chosen provider up via `onOauthPress`. No business logic.
 * @param props - provider items and the press callback
 */
export const OauthButtons = ({
    items,
    onOauthPress,
}: OauthButtonsProps) => {
    const t = useTranslations()
    const buttonItems = items.map((item) => () => (
        <Button
            variant="outline"
            label={t(item.labelKey)}
            prefixIcon={item.icon}
            classNames={["w-full"]}
            onPress={() => onOauthPress(item.provider)}
        />
    ))
    return <StackV identity={{ tier: "block", component: "OauthButtons" }} gap={3} items={buttonItems} />
}

"use client"

/**
 * **Sign-in step 1** — OAuth shortcuts, email/password, link to sign-up tab.
 *
 * Container: owns the sign-in formik (singleton `useSignInForm()`), the
 * router/dispatch wiring, and the OAuth redirect action; renders presentational
 * children as content only (no modal CloseTrigger / Header / Body).
 *
 * @see {@link SignInSection} for Redux step routing and folder conventions.
 */
import React, {
    useCallback,
    useMemo,
} from "react"
import { useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { OAUTH_BUTTON_ITEMS } from "./map"
import { OauthButtons } from "./OauthButtons"
import { EmailField } from "./EmailField"
import { PasswordField } from "./PasswordField"
import { RememberMeRow } from "./RememberMeRow"
import { SignUpPrompt } from "./SignUpPrompt"
import { useAppDispatch } from "@/redux/hooks"
import { AuthenticationModalTab, setAuthenticationModalTab } from "@/redux/slices/tabs"
import { useSignInForm } from "@/hooks/zustand/signIn/useSignInForm"
import { KeycloakIdentityProvider } from "@/modules/api/graphql/mutations/types/exchange-code-for-token"
import { keycloakRedirect } from "@/modules/api/redirect/keycloak"
import { SessionStorage } from "@/modules/storage/session/storage"
import { SessionStorageId } from "@/modules/storage/session/enums/id"
import { type SessionStorageOauthIdpHint } from "@/modules/storage/session/types/oauth-idp-hint"
import { type SessionStoragePostLoginRedirect } from "@/modules/storage/session/types/post-login-redirect"
import { useSearchParams } from "next/navigation"
import { Turnstile } from "@/components/blocks/auth/Turnstile"
import { publicEnv } from "@/resources/env/public"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Divider } from "@/components/atoms/display/Divider"
import { StackV } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/**
 * Credentials step container for the sign-in tab.
 */
export const CredentialsState = () => {
    const t = useTranslations()
    const searchParams = useSearchParams()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        setFieldTouched,
        isSubmitting,
    } = useSignInForm()

    const router = useRouter()
    const dispatch = useAppDispatch()

    /** Stable reference to the static OAuth button catalog. */
    const oauthButtons = useMemo(
        () => OAUTH_BUTTON_ITEMS,
        [],
    )

    /** Start the Keycloak OAuth redirect for the chosen provider. */
    const onOauthPress = useCallback(
        (provider: KeycloakIdentityProvider) => {
            // remember which IdP was used so the callback can resume the flow
            SessionStorage.setItem<SessionStorageOauthIdpHint>(
                SessionStorageId.OauthIdpHint,
                { provider },
            )
            // carry the originally-requested protected route (set by the edge guard as
            // `?redirect=`) through the Keycloak round-trip, since query params on THIS
            // page don't survive the IdP hop.
            const redirectTarget = searchParams.get("redirect")
            if (redirectTarget) {
                SessionStorage.setItem<SessionStoragePostLoginRedirect>(
                    SessionStorageId.PostLoginRedirect,
                    { target: redirectTarget },
                )
            }
            const url = provider === KeycloakIdentityProvider.Google
                ? keycloakRedirect.google
                : keycloakRedirect.github
            url.searchParams.set("redirect_uri", window.location.href)
            router.push(url.toString())
        },
        [
            router,
            searchParams,
        ],
    )

    const onChangeEmail = useCallback(
        (value: string) => {
            setFieldValue("email", value)
        },
        [
            setFieldValue,
        ],
    )

    const onChangePassword = useCallback(
        (value: string) => {
            setFieldValue("password", value)
        },
        [
            setFieldValue,
        ],
    )

    const onChangeRememberMe = useCallback(
        (selected: boolean) => {
            // third arg true: run validation so dependent errors clear
            setFieldValue("rememberMe", selected, true)
            setFieldTouched("rememberMe", true, false)
        },
        [
            setFieldValue,
            setFieldTouched,
        ],
    )

    const onSubmit = useCallback(
        () => {
            submitForm()
        },
        [
            submitForm,
        ],
    )

    const onSwitchToSignUp = useCallback(
        () => {
            dispatch(setAuthenticationModalTab(AuthenticationModalTab.SignUp))
        },
        [
            dispatch,
        ],
    )

    const isSubmitDisabled = publicEnv().captcha.enabled && !values.captchaToken

    const bodyItems = [
        () => (
            <Box className="pr-8">
                <StackV
                    gap={2}
                    principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    items={[
                        () => <Typography weight="semibold" align="center" text={t("auth.signIn.title")} />,
                        () => <Typography size="xs" color="muted" align="center" text={t("auth.signIn.desc")} />,
                    ]}
                />
            </Box>
        ),
        () => (
            <StackV
                gap={4}
                items={[
                    () => <OauthButtons items={oauthButtons} onOauthPress={onOauthPress} />,
                    () => <Divider label={t("auth.signIn.or")} />,
                ]}
            />
        ),
        () => (
            <StackV
                gap={4}
                items={[
                    () => (
                        <EmailField
                            value={values.email}
                            error={errors.email}
                            touched={touched.email}
                            onChangeValue={onChangeEmail}
                        />
                    ),
                    () => (
                        <PasswordField
                            value={values.password}
                            error={errors.password}
                            touched={touched.password}
                            onChangeValue={onChangePassword}
                        />
                    ),
                    () => (
                        <RememberMeRow
                            isSelected={values.rememberMe}
                            onChangeSelected={onChangeRememberMe}
                        />
                    ),
                ]}
            />
        ),
        ...(publicEnv().captcha.enabled ? [() => (
            <Turnstile
                onVerify={(token: string) => setFieldValue("captchaToken", token)}
                onExpire={() => setFieldValue("captchaToken", undefined)}
                onError={() => setFieldValue("captchaToken", undefined)}
            />
        )] : []),
        () => (
            <Button
                variant="primary"
                classNames={["w-full"]}
                isPending={isSubmitting}
                isDisabled={isSubmitDisabled}
                label={t("auth.signIn.submit")}
                onPress={onSubmit}
            />
        ),
        () => <SignUpPrompt onSwitchToSignUp={onSwitchToSignUp} />,
    ]

    return (
        <StackV
            identity={{ tier: "block", component: "CredentialsState" }}
            gap={6}
            items={bodyItems}
        />
    )
}

"use client"

/**
 * **Sign-in step 2** — OTP entry after `signInInit` succeeds.
 *
 * Same singleton Formik as credentials step. Description uses `t.rich` so the email can be styled.
 * Submit runs the OTP verify branch in `useSignInForm` while `signInState === OTP`.
 *
 * @see {@link SignInSection} for step routing; mirror this folder when sign-up adds a verify-email step.
 */
import { InputOtp } from "@/components/atoms/forms"
import React from "react"
import { useTranslations } from "next-intl"
import { useMutateSignInResendOtpSwr } from "@/hooks/swr/api/graphql/mutations/useMutateSignInResendOtpSwr"
import { useSignInForm } from "@/hooks/zustand/signIn/useSignInForm"
import { useGraphQLWithToast } from "@/modules/toast/hooks"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"

import { StackV, StackH } from "@/components/frames/Stack"
import { Box } from "@/components/frames/Box"

/**
 * OTPState component.
 */
export const OtpState = () => {
    const t = useTranslations()
    const runGraphQL = useGraphQLWithToast()
    const { trigger: mutateSignInResendOtp, isMutating: isResending } = useMutateSignInResendOtpSwr()
    const {
        values,
        errors,
        touched,
        submitForm,
        setFieldValue,
        isSubmitting,
    } = useSignInForm()

    const onResend = async () => {
        const challengeId = values.challengeId
        if (!challengeId) {
            return
        }
        await runGraphQL(
            async () => {
                const apolloResult = await mutateSignInResendOtp({
                    request: {
                        challengeId,
                    },
                })
                const env = apolloResult.data?.signInResendOtp
                if (!env?.success || !env.data?.challengeId) {
                    throw new Error(
                        env?.error ?? env?.message ?? "signInResendOtp failed"
                    )
                }
                await setFieldValue("challengeId", env.data.challengeId)
                await setFieldValue("otp", "", true)
                return env
            },
            {
                showErrorToast: true,
                showSuccessToast: true,
            }
        )
    }

    const otpInvalid = !!(touched.otp && errors.otp)

    const resendRow = [
        () => <Typography size="xs" color="muted" text={t("auth.signIn.otp.resend")} />,
        () => (
            <Typography
                size="xs"
                isLink
                color={isResending ? "muted" : "accent-soft"}
                onPress={() => {
                    if (isResending) return
                    void onResend()
                }}
                text={t("auth.signIn.otp.resendLink")}
            />
        ),
    ]

    const otpFieldItems = [
        () => (
            <InputOtp
                value={values.otp}
                onValueChange={(value) => setFieldValue("otp", value)}
                isInvalid={otpInvalid}
                errorMessage={otpInvalid ? errors.otp : undefined}
            />
        ),
        () => (
            <StackH
                gap={3}
                principle="flex-action"
                explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                justify="center"
                items={resendRow}
            />
        ),
    ]

    const bodyItems = [
        () => (
            <Box className="pr-8">
                <Typography weight="semibold" align="center" text={t("auth.signIn.otp.title")} />
            </Box>
        ),
        () => (
            <Typography
                size="xs"
                color="muted"
                align="center"
                text={t.rich("auth.signIn.otp.desc", {
                    emailHighlight: (chunks) => (
                        <span className="text-accent-soft-foreground">{chunks}</span>
                    ),
                    email: values.email,
                })}
            />
        ),
        () => (
            <StackV
                principle="sibling-stack"
                explain="OTP digit fields are same-kind peers in one column — not group-boundary, because they are repeating controls rather than section groups."
                items={otpFieldItems}
            />
        ),
        () => (
            <Button
                variant="primary"
                classNames={["w-full"]}
                isPending={isSubmitting}
                label={t("auth.signIn.otp.submit")}
                onPress={() => submitForm()}
            />
        ),
    ]

    return (
        <StackV
            identity={{ tier: "block", component: "SignInOtpState" }}
            principle="block-boundary"
            explain="Title over the OTP form — not group-boundary, because this is the panel body's major section seam."
            items={bodyItems}
        />
    )
}

import { InputOtp } from "@/components/atoms/forms"
import React, { type ReactNode } from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"

import { Box } from "@/components/frames/Box"
import { StackV, StackH } from "@/components/frames/Stack"
import { Form } from "@/components/composites/form/Form"

/** Already-translated strings {@link _OtpState} renders — resolved by the connected `OtpState`, never `t()`/`t.rich()` itself. */
export interface OtpStateLabels {
    title: string
    /** `t.rich(...)`-resolved description with the email highlighted — already a built node. */
    desc: ReactNode
    resend: string
    resendLink: string
    submit: string
}

/** Props for {@link _OtpState}. */
export interface OtpStateProps {
    /** Current 6-digit code value. */
    otp: string
    error?: string
    touched?: boolean
    /** True once the code passes format validation — gates the submit button. */
    isValid: boolean
    /** True while `signUpVerifyOtp` is in flight. */
    isSubmitting: boolean
    /** True while `signUpResendOtp` is in flight — locks the resend link. */
    isResending: boolean
    /** Already-translated strings — see {@link OtpStateLabels}. */
    labels: OtpStateLabels
    onChangeOtp: (value: string) => void
    /** Submit the form (the connected half runs `signUpVerifyOtp`). */
    onSubmit: () => void
    /** Request a fresh code (the connected half runs `signUpResendOtp`). */
    onResend: () => void
}

/**
 * Presentational OTP form — the second sign-up step, after `signUpInit`.
 * Content only: hosts supply chrome (`ModalShell` or page card).
 *
 * @param props - {@link OtpStateProps}
 */
export const _OtpState = ({
    otp,
    error,
    touched,
    isValid,
    isSubmitting,
    isResending,
    labels,
    onChangeOtp,
    onSubmit,
    onResend,
}: OtpStateProps) => {
    const showError = Boolean(touched && error)

    const resendRow = [
        () => <Typography size="xs" color="muted" text={labels.resend} />,
        () => (
            <Typography
                size="xs"
                color={isResending ? "muted" : "accent-soft"}
                isButton
                onPress={() => {
                    if (!isResending) onResend()
                }}
                text={labels.resendLink}
            />
        ),
    ]

    const otpFieldItems = [
        () => (
            <InputOtp
                length={6}
                value={otp}
                onValueChange={onChangeOtp}
                isInvalid={showError}
                errorMessage={showError ? error : undefined}
            />
        ),
        () => (
            <StackH
                principle="flex-action-center"
                explain="Resend OTP sits on one centered action baseline — not flex-action, because the row is cross-aligned to the midline rather than start."
                items={resendRow}
            />
        ),
    ]

    const formBodyItems = [
        () => <Typography size="xs" color="muted" align="center" text={labels.desc} />,
        () => (
            <StackV
                principle="sibling-stack"
                explain="OTP digit fields are same-kind peers in one column — not group-boundary, because they are repeating controls rather than section groups."
                items={otpFieldItems}
            />
        ),
    ]

    return (
        <StackV
            identity={{ tier: "block", component: "SignUpOtpState" }}
            principle="block-boundary"
            explain="Title over the OTP form — not group-boundary, because this is the panel body's major section seam."
            items={[
                () => (
                    <Box className="pr-8">
                        <Typography weight="semibold" align="center" text={labels.title} />
                    </Box>
                ),
                () => (
                    <Form
                        onSubmit={onSubmit}
                        gap={6}
                        body={() => (
                            <StackV
                                principle="block-boundary"
                                explain="Description over the OTP field stack — not sibling-stack, because the copy and the fields are different kinds of content."
                                items={formBodyItems}
                            />
                        )}
                        actions={() => (
                            <Button
                                variant="primary"
                                classNames={["w-full"]}
                                isDisabled={!isValid}
                                isPending={isSubmitting}
                                label={labels.submit}
                                onPress={onSubmit}
                            />
                        )}
                    />
                ),
            ]}
        />
    )
}

import React from "react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button } from "@/components/atoms/buttons/Button"
import { Box } from "@/components/frames/Box"
import { StackV } from "@/components/frames/Stack"
import { Form } from "@/components/composites/form/Form"
import { EmailField } from "./EmailField"
import { PasswordField } from "./PasswordField"
import { AgreeToTermsRow } from "./AgreeToTermsRow"
import { SignInPrompt } from "./SignInPrompt"
import { Turnstile } from "@/components/blocks/auth/Turnstile"

/** Editable values {@link _RegistrationState} renders. */
export interface RegistrationStateValues {
    email: string
    password: string
    confirmPassword: string
    agreeToTerms: boolean
}

/** Field-level validation errors, keyed the same as {@link RegistrationStateValues}. */
export interface RegistrationStateErrors {
    email?: string
    password?: string
    confirmPassword?: string
    agreeToTerms?: string
}

/** Which fields have been interacted with — gates when an error is shown. */
export interface RegistrationStateTouched {
    email?: boolean
    password?: boolean
    confirmPassword?: boolean
    agreeToTerms?: boolean
}

/** Already-translated strings {@link _RegistrationState} renders — resolved by the connected `RegistrationState`, never `t()` itself. */
export interface RegistrationStateLabels {
    title: string
    desc: string
    submit: string
}

/** Props for {@link _RegistrationState}. */
export interface RegistrationStateProps {
    values: RegistrationStateValues
    errors: RegistrationStateErrors
    touched: RegistrationStateTouched
    /** True while `signUpInit` is in flight — locks the submit button. */
    isSubmitting: boolean
    /** True when the form cannot be submitted yet (invalid, or captcha required but not solved). */
    isSubmitDisabled: boolean
    /** Whether the Cloudflare Turnstile widget should render at all. */
    captchaEnabled: boolean
    /** Already-translated strings — see {@link RegistrationStateLabels}. */
    labels: RegistrationStateLabels
    onChangeEmail: (value: string) => void
    onChangePassword: (value: string) => void
    onChangeConfirmPassword: (value: string) => void
    onChangeAgreeToTerms: (selected: boolean) => void
    /** Submit the form (the connected half runs `signUpInit`). */
    onSubmit: () => void
    /** Switch back to the sign-in tab. */
    onSwitchToSignIn: () => void
    onCaptchaVerify: (token: string) => void
    onCaptchaExpire: () => void
    onCaptchaError: () => void
}

/**
 * Presentational registration form — the first sign-up step (email, passwords,
 * terms). Content only: hosts supply chrome (`ModalShell` or page card).
 *
 * @param props - {@link RegistrationStateProps}
 */
export const _RegistrationState = ({
    values,
    errors,
    touched,
    isSubmitting,
    isSubmitDisabled,
    captchaEnabled,
    labels,
    onChangeEmail,
    onChangePassword,
    onChangeConfirmPassword,
    onChangeAgreeToTerms,
    onSubmit,
    onSwitchToSignIn,
    onCaptchaVerify,
    onCaptchaExpire,
    onCaptchaError,
}: RegistrationStateProps) => (
    <StackV
        identity={{ tier: "block", component: "RegistrationState" }}
        gap={6}
        items={[
            () => (
                <StackV
                    gap={2}
                    principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    items={[
                        () => (
                            <Box className="pr-8">
                                <Typography weight="semibold" align="center" text={labels.title} />
                            </Box>
                        ),
                        () => <Typography size="xs" color="muted" align="center" text={labels.desc} />,
                    ]}
                />
            ),
            () => (
                <Form
                    onSubmit={onSubmit}
                    gap={6}
                    body={() => (
                        <StackV
                            gap={6}
                            items={[
                                () => (
                                    <StackV
                                        gap={3}
                                        items={[
                                            () => (
                                                <EmailField
                                                    value={values.email}
                                                    error={errors.email}
                                                    touched={touched.email}
                                                    onChangeValue={onChangeEmail}
                                                />
                                            ),
                                            () => (
                                                <PasswordField
                                                    kind="password"
                                                    value={values.password}
                                                    error={errors.password}
                                                    touched={touched.password}
                                                    onChangeValue={onChangePassword}
                                                />
                                            ),
                                            () => (
                                                <PasswordField
                                                    kind="confirmPassword"
                                                    value={values.confirmPassword}
                                                    error={errors.confirmPassword}
                                                    touched={touched.confirmPassword}
                                                    onChangeValue={onChangeConfirmPassword}
                                                />
                                            ),
                                            () => (
                                                <AgreeToTermsRow
                                                    isSelected={values.agreeToTerms}
                                                    error={errors.agreeToTerms}
                                                    touched={touched.agreeToTerms}
                                                    onChangeSelected={onChangeAgreeToTerms}
                                                />
                                            ),
                                        ]}
                                    />
                                ),
                                ...(captchaEnabled
                                    ? [() => (
                                        <Turnstile
                                            onVerify={onCaptchaVerify}
                                            onExpire={onCaptchaExpire}
                                            onError={onCaptchaError}
                                        />
                                    )]
                                    : []),
                            ]}
                        />
                    )}
                    actions={() => (
                        <StackV
                            gap={6}
                            items={[
                                () => (
                                    <Button
                                        variant="primary"
                                        classNames={["w-full"]}
                                        isDisabled={isSubmitDisabled}
                                        isPending={isSubmitting}
                                        label={labels.submit}
                                        onPress={onSubmit}
                                    />
                                ),
                                () => <SignInPrompt onSwitchToSignIn={onSwitchToSignIn} />,
                            ]}
                        />
                    )}
                />
            ),
        ]}
    />
)

import React from "react"
import { SignInSection } from "./SignInSection"
import { SignUpSection } from "./SignUpSection"
import { AuthenticationModalTab } from "@/redux/slices/tabs"
import type { SkeletonProps } from "@/components/frames/_slot"

/** Props for {@link _AuthenticationPanel}. */
export interface AuthenticationPanelProps {
    /** Active auth tab — selects the sign-in or sign-up step machine. */
    tab: AuthenticationModalTab
}

/**
 * Presentational auth body — title + form content for whichever tab is active.
 * Owns no modal chrome (`CloseTrigger` / `Header` / `Body` / backdrop); hosts
 * ({@link AuthenticationModal} via `ModalShell`, {@link LoginPage} via page card)
 * supply the surface around this panel.
 *
 * @param props - {@link AuthenticationPanelProps}
 */
export const _AuthenticationPanel = ({
    tab,
}: SkeletonProps<AuthenticationPanelProps>) => {
    switch (tab) {
    case AuthenticationModalTab.SignIn:
        return <SignInSection />
    case AuthenticationModalTab.SignUp:
        return <SignUpSection />
    default:
        return null
    }
}

"use client"

import React, { useEffect, useRef } from "react"
import { publicEnv } from "@/resources/env/public"

/** Props for {@link Turnstile}. */
export interface TurnstileProps {
    /** Callback triggered when Turnstile successfully validates the visitor. */
    onVerify: (token: string) => void
    /** Callback triggered when Turnstile token expires. */
    onExpire?: () => void
    /** Callback triggered on network or verification error. */
    onError?: () => void
}

/** Render options passed to `turnstile.render()`. */
interface TurnstileRenderOptions {
    sitekey: string
    callback: (token: string) => void
    "expired-callback": () => void
    "error-callback": () => void
}

/** Minimal subset of the Cloudflare Turnstile global API used in this module. */
interface TurnstileApi {
    render: (container: HTMLElement, options: TurnstileRenderOptions) => string
    remove: (widgetId: string) => void
}

/** Window augmented with the optional Turnstile global. */
interface WindowWithTurnstile extends Window {
    turnstile?: TurnstileApi
}

/**
 * Renders the Cloudflare Turnstile captcha widget dynamically.
 * Automatically loads the Turnstile script if not already present.
 * No-ops (returns null) when captcha is disabled in public config.
 */
export const Turnstile = ({ onVerify, onExpire, onError}: TurnstileProps) => {
    const containerRef = useRef<HTMLDivElement>(null)
    const widgetIdRef = useRef<string | null>(null)

    useEffect(() => {
        const { enabled, siteKey } = publicEnv().captcha
        if (!enabled) return

        let isMounted = true

        const renderWidget = () => {
            const turnstile = (window as WindowWithTurnstile).turnstile
            if (!isMounted || !containerRef.current || !turnstile) return

            try {
                if (widgetIdRef.current !== null) {
                    turnstile.remove(widgetIdRef.current)
                }

                widgetIdRef.current = turnstile.render(containerRef.current, {
                    sitekey: siteKey,
                    callback: (token: string) => {
                        if (isMounted) onVerify(token)
                    },
                    "expired-callback": () => {
                        if (isMounted && onExpire) onExpire()
                    },
                    "error-callback": () => {
                        if (isMounted && onError) onError()
                    },
                })
            } catch (err) {
                console.error("[Turnstile] Render error:", err)
            }
        }

        const scriptId = "cloudflare-turnstile-script"
        let script = document.getElementById(scriptId) as HTMLScriptElement | null

        if (!script) {
            script = document.createElement("script")
            script.id = scriptId
            script.src = "https://challenges.cloudflare.com/turnstile/v0/api.js?render=explicit"
            script.async = true
            script.defer = true
            document.body.appendChild(script)
        }

        const turnstile = (window as WindowWithTurnstile).turnstile
        if (turnstile) {
            renderWidget()
        } else {
            const onLoad = () => {
                renderWidget()
            }
            script.addEventListener("load", onLoad)
            return () => {
                isMounted = false
                script?.removeEventListener("load", onLoad)
                const activeTurnstile = (window as WindowWithTurnstile).turnstile
                if (widgetIdRef.current !== null && activeTurnstile) {
                    activeTurnstile.remove(widgetIdRef.current)
                }
            }
        }

        return () => {
            isMounted = false
            const activeTurnstile = (window as WindowWithTurnstile).turnstile
            if (widgetIdRef.current !== null && activeTurnstile) {
                activeTurnstile.remove(widgetIdRef.current)
            }
        }
    }, [onVerify, onExpire, onError])

    const { enabled } = publicEnv().captcha
    if (!enabled) return null

    return <div ref={containerRef} className={"flex justify-center my-2 min-h-[74px]"} />
}
export default Turnstile

