import React from "react"
import type { ReactNode } from "react"
import { Typography, cn } from "@heroui/react"
import { ImageIcon } from "@phosphor-icons/react"
import { useDropzone } from "react-dropzone"

/** Max image size in bytes (5 MB — mirrors the BE avatar limit). */
const MAX_SIZE = 5 * 1024 * 1024

/** Accepted image MIME types. */
const ACCEPT = {
    "image/png": [],
    "image/jpeg": [],
    "image/webp": [],
    "image/gif": [],
}

/** Props for the {@link ImageDropzone} block. */
export interface ImageDropzoneProps {
    /** Called with the dropped / picked image file (type + size filtered). */
    onFile: (file: File) => void
    /** Primary CTA (e.g. "Drag and drop an image here, or click to choose"). */
    label: ReactNode
    /** Format/size hint below the CTA (e.g. "PNG, JPG, WEBP, GIF · up to 5 MB"). */
    hint?: ReactNode
    /** Override the default {@link ImageIcon} (phosphor `*Icon`). */
    icon?: ReactNode
}

/**
 * Standard file dropzone (react-dropzone) for a single image: a dashed-border area
 * with a centered column — an icon, the CTA label, and a format hint. Accepts one
 * image (png/jpeg/webp/gif, ≤5 MB) by drop OR click; on drag-over the border turns
 * solid accent with a soft tint and the icon/label highlight (clear "drop here"
 * state). Pure/props-only — owns its look; the feature handles the file.
 *
 * @param props - {@link ImageDropzoneProps}
 *
 * @see Story: .storybook/stories/blocks/identity/ImageDropzone/ImageDropzone.stories
 */
export const ImageDropzone = ({ onFile, label, hint, icon}: ImageDropzoneProps) => {
    const { getRootProps, getInputProps, isDragActive } = useDropzone({
        accept: ACCEPT,
        maxSize: MAX_SIZE,
        multiple: false,
        onDrop: (accepted) => {
            const next = accepted[0]
            if (next) {
                onFile(next)
            }
        },
    })

    return (
        <div
            {...getRootProps()}
            className={cn("flex cursor-pointer flex-col items-center gap-2 rounded-2xl border border-dashed border-separator px-6 py-8 text-center transition-colors hover:border-accent",
                isDragActive && "border-solid border-accent bg-accent-soft")}
        >
            <input {...getInputProps()} />
            <span
                aria-hidden
