            >
                {icon ?? <ImageIcon focusable="false" />}
            </span>
            <Typography
                type="body-sm"
                weight="medium"
                align="center"
                className={cn(isDragActive && "text-accent-soft-foreground")}
            >
                {label}
            </Typography>
            {hint ? (
                <Typography type="body-xs" color="muted" align="center">
                    {hint}
                </Typography>
            ) : null}
        </div>
    )
}

"use client"

import React from "react"
import { Avatar, AvatarFallback, AvatarImage, cn } from "@heroui/react"
import { dicebearAvatarUrl } from "@/utils/avatar"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link UserAvatar}. */
export interface UserAvatarProps extends WithClassNames<undefined> {
    /** Display username; drives the initials fallback + image alt text. */
    username?: string | null
    /** Uploaded avatar URL; when missing OR it fails to load, a generated default is shown. */
    avatar?: string | null
    /**
     * Stable identity used to seed the generated default avatar (email preferred,
     * else username/name). Falls back to `username` when omitted.
     */
    seed?: string | null
    /** HeroUI avatar size preset. */
    size?: "sm" | "md" | "lg"
}

/**
 * Shared user avatar with a resilient fallback chain:
 *   1. the user's uploaded image (when present),
 *   2. a deterministic generated (DiceBear) avatar seeded by their identity,
 *   3. the first two letters of their username, as a last resort.
 *
 * Crucially the chain advances on *load failure*, not just on a missing URL — so a
 * stale/broken uploaded URL still resolves to the generated face instead of bare
 * initials. Same seed → same face everywhere the user is shown.
 *
 * @param props - {@link UserAvatarProps}
 * @see Story: .storybook/stories/blocks/identity/UserAvatar/UserAvatar.stories
 */
export const UserAvatar = ({ username, avatar, seed, size, className }: UserAvatarProps) => {
    // last-resort fallback if even the generated image fails to load
    const initials = (username ?? "").slice(0, 2).toUpperCase()
    // ordered image candidates: uploaded first, then the stable generated default
    const candidates = React.useMemo(() => {
        const uploaded = avatar?.trim()
        const generated = dicebearAvatarUrl((seed ?? username) ?? "")
        return uploaded ? [uploaded, generated] : [generated]
    }, [avatar, seed, username])

    // index of the candidate currently being attempted; advances on load error.
    // keyed by the candidate signature so it resets when the user/avatar changes.
    const signature = candidates.join("|")
    const [state, setState] = React.useState({ signature, index: 0 })
    const index = state.signature === signature ? state.index : 0
    const src = candidates[index]

    return (
        <Avatar size={size} className={cn("rounded-full", className)}>
            {/*
              Radix only mounts the <img> once it has loaded, so a broken src never
              fires onError on the element — it reports failure via onLoadingStatusChange.
              On "error" we advance to the next candidate; when exhausted, the fallback shows.
            */}
            {src ? (
                <AvatarImage
                    src={src}
                    alt={username ?? ""}
                    onLoadingStatusChange={(status) => {
                        if (status === "error") {
                            setState({ signature, index: index + 1 })
                        }
                    }}
                />
            ) : null}
            <AvatarFallback>{initials}</AvatarFallback>
        </Avatar>
    )
}

"use client"

import React, { useEffect, useRef, useState } from "react"
import { codeToHtml } from "shiki"
import { cn } from "@heroui/react"
import { SnippetIcon } from "@/components/blocks/identity/SnippetIcon"

/** Props for {@link CodeToHtml}. */
export interface CodeToHtmlProps {
    /** Source code to highlight. */
    code: string
    /** Shiki language id (e.g. `bash`, `ts`). */
    language: string
    /** Shiki theme id resolved from the app theme. */
    theme: string
    /**
     * Surface treatment (both variants are `rounded-3xl` — a code block is
     * card-like). Default (`false`) = RECESSED well (`border border-default
     * bg-background`) — the correct look when the block sits ON a reading surface /
     * card (a bg-background inset reads as darker than the surface around it). Set
     * `true` for a RAISED card (`bg-surface shadow-surface`, NO border — shadow
     * does the lifting, axis-1 §16/§32) when the block sits on the page CANVAS
     * (`bg-background`), so it "floats up" instead of blending canvas-on-canvas.
     * Only opt in where the container is the bare canvas.
     */
    elevated?: boolean
}

/**
 * Converts a code block to highlighted HTML using Shiki.
 *
 * Presentational: runs Shiki in a `useEffect` and stores the resulting HTML in local state;
 * no business logic. Marked `"use client"` for the browser-side highlighter.
 *
 * PERF: highlighting is LAZY — only run Shiki when the block scrolls near the viewport
 * (IntersectionObserver). A long article with 20+ blocks won't highlight all at once on load
 * (Shiki/WASM is heavy); off-screen blocks show raw code (`<pre>`) until scrolled into view.
 * @param props - {@link CodeToHtmlProps}
 * @see Story: .storybook/stories/blocks/rendering/MarkdownContent/CodeToHtml/CodeToHtml.stories
 */
export const CodeToHtml = ({ code, language, theme, elevated = false }: CodeToHtmlProps) => {
    const containerRef = useRef<HTMLDivElement>(null)
    /** Whether the block has entered (near) the viewport yet — only then do we highlight. */
    const [isVisible, setIsVisible] = useState(false)
    /** Highlighted HTML; `null` keeps the raw `<pre>` fallback. */
    const [html, setHtml] = useState<string | null>(null)

    useEffect(() => {
        const el = containerRef.current
        if (!el || isVisible) {
            return
        }
        const observer = new IntersectionObserver(
            (entries) => {
                if (entries[0]?.isIntersecting) {
                    setIsVisible(true)
                    observer.disconnect()
                }
            },
            // rootMargin: start highlighting 300px before the block enters the screen.
            { rootMargin: "300px" },
        )
        observer.observe(el)
        return () => observer.disconnect()
    }, [isVisible])

    // Run Shiki via useEffect (no SWR) directly client-side once the block is visible.
    // Changing code/language/theme must re-highlight. `cancelled` blocks setState after unmount /
    // when deps change mid-flight (avoids writing stale HTML over newer HTML).
    useEffect(() => {
        if (!isVisible) {
            return
        }
        let cancelled = false
        codeToHtml(code, { lang: language, theme })
            .then((out) => {
                if (!cancelled) {
                    setHtml(out)
                }
            })
            .catch((error) => {
                // Shiki error (lang/theme/WASM…): keep the raw `<pre>` fallback + log for debugging.
                console.error("CodeToHtml: shiki highlight failed", error)
            })
        return () => {
            cancelled = true
        }
    }, [isVisible, code, language, theme])

    return (
        <div
            ref={containerRef}
            className={cn(
                // BOTH variants = rounded-3xl (a code block is card-like → 3xl
                // regardless of treatment, instructor's call, 2026-07-18). Only bg/shadow differ:
                // raised card ON canvas (`bg-surface shadow`, NO border — shadow
                // lifts, axis-1 §16/§32) vs recessed well ON a surface (`bg-background`
                // inset + border, so it doesn't fill-on-fill the surface around it).
                "w-full max-w-full overflow-hidden rounded-3xl",
                elevated
                    ? "bg-surface shadow-surface"
                    : "border border-default bg-background",
            )}
        >
            {/* slim header: language label (left) + copy (right) — orients long lessons with many snippets */}
            <div className="flex items-center justify-between border-b border-default px-3 py-2">
                <span className="font-mono text-xs uppercase text-muted">{language}</span>
                <SnippetIcon copyString={code} />
            </div>
            {html ? (
                <div
                    className="p-3 text-sm [&_code]:!whitespace-pre-wrap [&_code]:!break-words [&_pre]:!whitespace-pre-wrap [&_pre]:!break-words [&_pre]:!bg-transparent [&_pre]:!p-0"
                    dangerouslySetInnerHTML={{ __html: html }}
                />
            ) : (
                /* Fallback: always show raw code while Shiki hasn't finished / on error (avoids an empty box). */
                <pre className="p-3 text-sm whitespace-pre-wrap break-words">
                    <code>{code}</code>
                </pre>
            )}
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
/** Props for {@link LayoutWidget}. */
export interface LayoutWidgetProps {
    /** Raw HTML layout-mockup source authored inside a ```layout fence. */
    html: string
}

/**
 * Strips active content from author-supplied HTML before it is injected via
 * `dangerouslySetInnerHTML`. Removes `<script>`/`<iframe>` elements, inline `on*=`
 * event-handler attributes, and `javascript:` URLs so a layout mockup can only paint
 * static markup. Deliberately minimal (no new dependency) — the input is trusted-author
 * lesson content, this is a defense-in-depth scrub, not a full sanitizer.
 * @param html - Raw HTML string from the fenced `layout` block.
 * @returns Sanitized HTML safe to render inline.
 */
const sanitizeLayoutHtml = (html: string): string =>
    html
        // Drop <script>…</script> blocks entirely (including their content).
        .replace(/<script\b[^>]*>[\s\S]*?<\/script\s*>/gi, "")
        // Drop any stray opening/closing <script> tags left without a pair.
        .replace(/<\/?script\b[^>]*>/gi, "")
        // Drop <iframe>…</iframe> blocks and any stray iframe tags.
        .replace(/<iframe\b[^>]*>[\s\S]*?<\/iframe\s*>/gi, "")
        .replace(/<\/?iframe\b[^>]*>/gi, "")
        // Strip inline event-handler attributes (onclick=, onload=, …), quoted or bare.
        .replace(/\son[a-z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, "")
        // Neutralize javascript: URLs in any remaining attribute value.
        .replace(/javascript:/gi, "")

/**
 * Renders an author-embedded HTML layout mockup inline within lesson markdown.
 *
 * Presentational: sanitizes the supplied HTML (see {@link sanitizeLayoutHtml}) and paints it
 * via `dangerouslySetInnerHTML` inside a bordered, rounded surface that works in light and
 * dark mode. `not-prose` keeps the prose typography from leaking into the mockup. Marked
 * `"use client"` so it pairs with the client-rendered markdown tree.
 * @param props - {@link LayoutWidgetProps}
 */
export const LayoutWidget = ({ html}: LayoutWidgetProps) => {
    // Memoize the scrub so re-renders don't re-run the regex passes over the same source.
    const safeHtml = useMemo(() => sanitizeLayoutHtml(html), [html])
    return (
        <div
            className={"not-prose overflow-hidden rounded-xl border border-default bg-surface"}
            dangerouslySetInnerHTML={{ __html: safeHtml }}
        />
    )
}

import { MagnifyingGlassPlusIcon } from "@phosphor-icons/react"
import React, { useState } from "react"
import { Modal } from "@heroui/react"

/** Props for {@link _MermaidDiagram} — presentational; the rendered SVG already resolved. */
export interface MermaidDiagramProps {
    /** Rendered SVG markup, or `null` while the diagram is still compiling. */
    svg: string | null
    /** Translated loading text while the diagram is rendering. */
    loadingLabel: string
    /** Translated accessible label for the click-to-zoom trigger. */
    expandLabel: string
    /** Figure caption paragraph that follows the diagram (e.g. "Figure 1: ..."), if any. */
    caption?: string
    /** Translated generic caption shown when the diagram has no authored caption. */
    fallbackLabel: string
}

/**
 * Renders a mermaid diagram's already-compiled SVG, with a click-to-zoom
 * full-screen preview.
 *
 * Presentational: the connected half owns the SWR-cached `mermaid.render()`
 * call; this component only toggles the full-screen preview (`useState`,
 * UI-local) and lays the SVG out. Marked `"use client"` via the connected
 * half — this file itself needs no browser API.
 * @param props - {@link MermaidDiagramProps}
 */
export const _MermaidDiagram = ({ svg, loadingLabel, expandLabel, caption, fallbackLabel }: MermaidDiagramProps) => {
    // Local open flag for the full-screen preview dialog (per-diagram, not a global modal).
    const [isOpen, setOpen] = useState(false)
    // Authored caption wins; otherwise show a generic figure label.
    const figureCaption = caption ?? fallbackLabel

    return (
        <figure className="rounded-xl border border-default bg-background p-3">
            {svg ? (
                <>
                    {/* Clickable inline diagram — opens the full-screen preview on press. */}
                    <button
                        type="button"
                        aria-label={expandLabel}
                        title={expandLabel}
                        onClick={() => setOpen(true)}
                        className="group relative block w-full cursor-zoom-in"
                    >
                        {/* mermaid stamps an inline `style="max-width:Npx"` on the <svg> that
                            outranks our `max-w-full` class, so a wide diagram would otherwise push
                            the reading column past the viewport. Wrap it in an x-scroll box. */}
                        <div
                            className="overflow-x-auto [&_svg]:h-auto [&_svg]:!w-auto [&_svg]:!max-w-none"
                            dangerouslySetInnerHTML={{ __html: svg }}
                        />
                        {/* Hover affordance hinting the diagram can be enlarged. */}
                        <span className="pointer-events-none absolute right-2 top-2 rounded-medium bg-default/60 p-2 text-muted opacity-0 transition-opacity group-hover:opacity-100">
                            <MagnifyingGlassPlusIcon className="size-5" />
                        </span>
                    </button>
                    {/* Authored caption ("Figure N: …") as a real figcaption — the source paragraph
                        is stripped upstream so it isn't shown twice. Generic fallback stays modal-only. */}
                    {caption ? (
                        <figcaption className="mt-2 text-center text-sm italic text-muted">
                            {caption}
                        </figcaption>
                    ) : null}
                    <Modal isOpen={isOpen} onOpenChange={setOpen}>
                        <Modal.Backdrop>
                            <Modal.Container size="full">
                                <Modal.Dialog>
                                    <Modal.CloseTrigger />
                                    <Modal.Body data-principle="card-padding" className="p-4">
                                        {/* Full-screen figure: diagram scaled to fill, caption beneath. */}
                                        <figure className="flex h-full flex-col items-center justify-center gap-2">
                                            <div className="flex w-full flex-1 items-center justify-center overflow-auto">
                                                <div
                                                    className="[&_svg]:h-auto [&_svg]:w-full [&_svg]:max-w-full"
                                                    dangerouslySetInnerHTML={{ __html: svg }}
                                                />
                                            </div>
                                            <figcaption className="text-center text-sm italic text-muted">
                                                {figureCaption}
                                            </figcaption>
                                        </figure>
                                    </Modal.Body>
                                </Modal.Dialog>
                            </Modal.Container>
                        </Modal.Backdrop>
                    </Modal>
                </>
            ) : (
                <div className="text-sm text-muted">{loadingLabel}</div>
            )}
        </figure>
    )
}

import React from "react"
import { cn, Spinner } from "@heroui/react"
import { heroUiMdxComponents } from "../mdxComponents"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Compiled MDX module exposes its content as the default export. */
export type MdxContentComponent = React.ComponentType<{
    components?: Record<string, React.ElementType>
    className?: string
}>

/** Props for {@link _RenderReactComponent} — presentational; the compiled MDX component already resolved. */
export interface RenderReactComponentProps extends WithClassNames<undefined> {
    /** JSX/MDX source (shown verbatim on a compile error). */
    code: string
    /** The compiled MDX component, or `null` while compiling. */
    Content: MdxContentComponent | null
    /** `true` → the compile failed; falls back to showing `code` verbatim. */
    hasError: boolean
}

/**
 * Renders a ` ```mdx ` snippet as a REAL React tree — render ONLY, no tabs.
 *
 * Presentational: the connected half owns the (browser-only) `evaluate()`
 * compile, cached per-source via SWR; this component only picks the
 * error / loading / compiled branch. On a compile error the raw snippet is
 * shown verbatim (safe fallback) instead of crashing.
 * @param props - {@link RenderReactComponentProps}
 */
export const _RenderReactComponent = ({ code, Content, hasError, className }: RenderReactComponentProps) => {
    if (hasError) {
        return (
            <pre className={cn("not-prose overflow-auto rounded-xl border border-danger/40 bg-default/40 p-3 font-mono text-xs text-muted", className)}>
                {code}
            </pre>
        )
    }
    if (!Content) {
        return <Spinner size="sm" aria-label="Rendering" className={cn(className)} />
    }
    return <Content components={heroUiMdxComponents} className={className} />
}

"use client"

import React from "react"
import { CodePreviewTabs } from "../CodePreviewTabs"

interface TabPaneProps {
    kind: "code" | "preview"
    children?: React.ReactNode
}

/**
 * One pane inside a `:::tab` block: the source code (`:::code` → ` ```tsx ` Shiki) or the live
 * demo (`:::preview` → ` ```mdx ` render). It only renders its children (the fence rendered by the
 * normal `pre` handler); {@link TabsBlock} identifies which pane is which by the original directive
 * tag name (`tabcode`/`tabpreview`), not by this prop.
 */

export const TabPane = (
    { children }: TabPaneProps,
) => <>{children}</>

/** The hast node react-markdown threads onto every element renderer via the `node` prop. */
interface NodeProp {
    node?: { tagName?: string }
}

/** Props for {@link TabsBlock}. */
interface TabsBlockProps {
    children?: React.ReactNode
}

/**
 * Renders a `:::tab` block as **[ Preview | Code ]** tabs via the shared {@link CodePreviewTabs}.
 *
 * Use this (not a single ` ```mdx `) when the real code has logic/imports that can't be evaluated:
 * the `:::code` pane shows the FULL code (Shiki, not rendered) and the `:::preview` pane shows a
 * separate renderable demo.
 *
 * Panes are matched by the original directive tag name carried on each child's `node` prop
 * (`tabcode` / `tabpreview`) — order-independent. NOTE: the children TabsBlock receives are the
 * `tabcode`/`tabpreview` element renderers themselves, whose own props are only `{ node, children }`;
 * the `kind` lives on the `TabPane` they *return*, so it is NOT visible here — match on `node.tagName`.
 * @param props.children - The `:::code` / `:::preview` pane elements.
 */
export const TabsBlock = ({ children }: TabsBlockProps) => {
    let previewNode: React.ReactNode = null
    let codeNode: React.ReactNode = null
    React.Children.forEach(children, (child) => {
        if (!React.isValidElement(child)) {
            return
        }
        const tagName = (child.props as NodeProp).node?.tagName
        if (tagName === "tabpreview") {
            previewNode = child
        } else if (tagName === "tabcode") {
            codeNode = child
        }
    })

    if (previewNode == null && codeNode == null) {
        return <>{children}</>
    }
    return <CodePreviewTabs preview={previewNode} code={codeNode} />
}

import React, { useMemo } from "react"
import ReactMarkdown from "react-markdown"
import remarkGfm from "remark-gfm"
import remarkDirective from "remark-directive"
import { cn } from "@heroui/react"
import type { Components } from "react-markdown"
// Re-export the colocated sub-renderers so the reuseable barrel surface stays identical.
export * from "./CodeToHtml"
export * from "./LayoutWidget"
export * from "./MermaidDiagram"

/**
 * Recursively rewrites `:::muted` directives (container/leaf/text, parsed by `remark-directive`)
 * into custom hast tags the renderer map styles as small muted text. Container/leaf → block-level
 * `mutedblock`; inline `:muted[…]` → `mutedtext`. Directives with any other name are left untouched
 * (and dropped by the hast conversion since they have no handler).
 * @param node - Current mdast node being walked.
 */
const applyMutedDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (
        (node.type === "containerDirective" || node.type === "leafDirective" || node.type === "textDirective")
        && node.name === "muted"
    ) {
        const data = node.data || (node.data = {})
        data.hName = node.type === "textDirective" ? "mutedtext" : "mutedblock"
        data.hProperties = {}
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyMutedDirective(child as Parameters<typeof applyMutedDirective>[0])
        }
    }
}

/** remark transformer: turn `:::muted` directives into styled custom tags. */
const remarkMuted = () => (tree: unknown): void => {
    applyMutedDirective(tree as Parameters<typeof applyMutedDirective>[0])
}

/**
 * Recursively rewrites the `:::tab` / `:::code` / `:::preview` container directives into custom hast
 * tags the renderer map turns into a [Preview|Code] tabs block (see TabsBlock): `tab`→`tabblock`,
 * `code`→`tabcode`, `preview`→`tabpreview`. Each pane's child fence (` ```tsx ` / ` ```mdx `) still
 * renders through the normal `pre` handler. Other directive names are left untouched.
 *
 * Note: container nesting needs MORE colons on the outer fence — `::::tab` wraps `:::code` /
 * `:::preview`.
 * @param node - Current mdast node being walked.
 */
const applyTabDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective") {
        const tag = node.name === "tab"
            ? "tabblock"
            : node.name === "code"
                ? "tabcode"
                : node.name === "preview"
                    ? "tabpreview"
                    : null
        if (tag) {
            const data = node.data || (node.data = {})
            data.hName = tag
            data.hProperties = {}
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyTabDirective(child as Parameters<typeof applyTabDirective>[0])
        }
    }
}

/** remark transformer: turn `::::tab`/`:::code`/`:::preview` directives into tabs-block tags. */
const remarkTab = () => (tree: unknown): void => {
    applyTabDirective(tree as Parameters<typeof applyTabDirective>[0])
}

/**
 * Recursively collects the raw text of a directive subtree, preserving line breaks so each
 * authored line (one keyword per line) can be split back out into a separate chip.
 * @param node - Current mdast node.
 */
const collectDirectiveText = (node: { type?: string, value?: string, children?: Array<unknown> }): string => {
    if (node.type === "text") {
        return node.value ?? ""
    }
    if (node.type === "break") {
        return "\n"
    }
    if (Array.isArray(node.children)) {
        return node.children
            .map((child) => collectDirectiveText(child as Parameters<typeof collectDirectiveText>[0]))
            .join("\n")
    }
    return ""
}

/**
 * Rewrites the `:::chip` container directive into a custom `chipblock` tag (see map.tsx),
 * carrying its keywords (one per authored line) as a newline-split, `|`-joined `items` prop so the
 * renderer can render each as its own Chip. Other directive names are left untouched.
 * @param node - Current mdast node being walked.
 */
const applyChipDirective = (node: { type?: string, name?: string, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective" && node.name === "chip") {
        const items = collectDirectiveText(node)
            .split(/[\n·]+/)
            .map((line) => line.trim())
            .filter((line) => line.length > 0)
        const data = node.data || (node.data = {})
        data.hName = "chipblock"
        data.hProperties = {
            items: items.join("|"),
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyChipDirective(child as Parameters<typeof applyChipDirective>[0])
        }
    }
}

/** remark transformer: turn `:::chip` directives into a chips-row tag. */
const remarkChip = () => (tree: unknown): void => {
    applyChipDirective(tree as Parameters<typeof applyChipDirective>[0])
}

/**
 * Recursively rewrites the `::::accordion` / `:::panel` container directives into custom hast tags the
 * renderer map turns into a HeroUI Accordion (see map.tsx): `accordion`→`accordionblock`; each
 * `:::panel{title="…"}`→`accordionpanel` carrying its `title` attribute. Inner panel content
 * (bullets, code fences) still renders through the normal handlers.
 *
 * Note: nesting needs MORE colons on the outer fence — `::::accordion` wraps `:::panel`.
 * @param node - Current mdast node being walked.
 */
const applyAccordionDirective = (node: { type?: string, name?: string, attributes?: Record<string, string>, data?: Record<string, unknown>, children?: Array<unknown> }): void => {
    if (node.type === "containerDirective") {
        if (node.name === "accordion") {
            const data = node.data || (node.data = {})
            data.hName = "accordionblock"
            data.hProperties = {}
        } else if (node.name === "panel") {
            const data = node.data || (node.data = {})
            data.hName = "accordionpanel"
            data.hProperties = {
                title: node.attributes?.title ?? "",
            }
        }
    }
    if (Array.isArray(node.children)) {
        for (const child of node.children) {
            applyAccordionDirective(child as Parameters<typeof applyAccordionDirective>[0])
        }
    }
}

/** remark transformer: turn `::::accordion`/`:::panel` directives into accordion tags. */
const remarkAccordion = () => (tree: unknown): void => {
    applyAccordionDirective(tree as Parameters<typeof applyAccordionDirective>[0])
}

/**
 * True for a `:::muted` directive node — already tagged `hName: "mutedblock"` by
 * {@link remarkMuted}. Its OWN content shape then decides how {@link groupArcSections}
 * handles it — see {@link isSelfContainedLeadBoldMuted} / {@link isBareLabelMuted}.
 * @param node - Current mdast node.
 */
const isMutedLabelNode = (node: { data?: { hName?: unknown } }): boolean => node.data?.hName === "mutedblock"

/**
 * True for the actual authoring idiom found in the card catalog: ONE paragraph
 * that OPENS with a `**bold**` span and keeps going as prose on the same line/block
 * (`**Solution** — NestJS provides three hooks...`) — label and body live in the SAME
 * mdast paragraph node. Two places this shape shows up: as a bare top-level
 * paragraph, OR (the actual catalog convention) as the sole child of a `:::muted`
 * directive — see {@link isSelfContainedLeadBoldMuted}.
 * @param node - Current mdast node.
 */
const isLeadBoldParagraph = (node: { type?: string, children?: Array<{ type?: string }> }): boolean =>
    node.type === "paragraph"
    && Array.isArray(node.children)
    && node.children.length > 0
    && node.children[0]?.type === "strong"

/**
 * True when a `:::muted` directive's ENTIRE content is one {@link isLeadBoldParagraph}
 * — the real catalog shape (`:::muted\n**Solution** — NestJS provides...\n:::`),
 * where the directive is a pointless extra wrapper around an already-self-contained
 * section. {@link groupArcSections} unwraps it (tags the inner paragraph directly)
 * instead of double-wrapping, which is what caused the infinite recursion this fixes
 * — re-processing a wrapper whose only child is still `hName: "mutedblock"` kept
 * re-matching {@link isMutedLabelNode} forever.
 * @param node - Current mdast node (already confirmed a muted label via {@link isMutedLabelNode}).
 */
const isSelfContainedLeadBoldMuted = (node: { children?: Array<{ type?: string, children?: Array<{ type?: string }> }> }): boolean =>
    Array.isArray(node.children) && node.children.length === 1 && isLeadBoldParagraph(node.children[0])

/**
 * True when a `:::muted` directive's ENTIRE content is ONE short inline node (the
 * doc-documented shape: `:::muted\n<Label>\n:::\n<body>` — label alone, body
 * follows as an external sibling). {@link groupArcSections} wraps this shape and
 * absorbs the following siblings as its body, unlike {@link isSelfContainedLeadBoldMuted}
 * which already has its body inside.
 * @param node - Current mdast node (already confirmed a muted label via {@link isMutedLabelNode}).
 */
const isBareLabelMuted = (node: { children?: Array<{ type?: string, children?: Array<unknown> }> }): boolean => {
    const only = node.children?.[0]
    return Array.isArray(node.children) && node.children.length === 1
        && only?.type === "paragraph"
        && Array.isArray(only.children) && only.children.length === 1
}

/**
 * Turns each Interview Arc section into one `arcsection` node so the renderer
 * (`map.tsx`) can box/collapse a whole "label + body" unit instead of rendering it
 * as flat, undifferentiated siblings/prose. Three authoring shapes exist in the card
 * catalog and are handled differently:
 * - `:::muted` wrapping a lead-bold paragraph (see {@link isSelfContainedLeadBoldMuted},
 *   the actual catalog convention) — the directive is unwrapped; its inner paragraph
 *   is retagged directly.
 * - Bare `:::muted` label (see {@link isBareLabelMuted}, the shape documented in
 *   `.claude/docs/rules/flashcard-answer.md` §2) — wrapped, absorbing every sibling
 *   that follows up to the next label as its body.
 * - Bare lead-bold paragraph, no `:::muted` at all — retagged in place.
 * Every node this function tags or wraps is added to `skip` so the second pass never
 * re-descends into it — re-visiting a `hName: "mutedblock"` node nested one level
 * inside its own freshly-created wrapper is what caused unbounded recursion before
 * this fix (a single-child wrapper around a still-muted-tagged node kept re-matching
 * and re-wrapping itself forever). Each `arcsection` carries its position (`index`,
 * 0-based) so the renderer can keep the first two sections (TL;DR / mechanism) always
 * expanded and collapse the rest behind a chip — the fixed order documented in
 * `.claude/docs/rules/flashcard-answer.md` §2.
 * @param node - Current mdast node being walked.
 */
const groupArcSections = (node: { children?: Array<Record<string, unknown>> }): void => {
    if (!Array.isArray(node.children)) {
        return
    }
    const grouped: Array<Record<string, unknown>> = []
    let current: { type: string, children: Array<unknown>, data: Record<string, unknown> } | null = null
    let sectionIndex = 0
    const skip = new Set<unknown>()
    for (const child of node.children) {
        if (isMutedLabelNode(child as Parameters<typeof isMutedLabelNode>[0])) {
            if (isSelfContainedLeadBoldMuted(child as Parameters<typeof isSelfContainedLeadBoldMuted>[0])) {
                const inner = (child.children as Array<Record<string, unknown>>)[0]
                const data = (inner.data as Record<string, unknown>) || (inner.data = {})
                data.hName = "arcsection"
                data.hProperties = { index: sectionIndex }
                sectionIndex += 1
                current = null
                grouped.push(inner)
                skip.add(inner)
            } else if (isBareLabelMuted(child as Parameters<typeof isBareLabelMuted>[0])) {
                current = {
                    type: "arcSection",
                    children: [child],
                    data: { hName: "arcsection", hProperties: { index: sectionIndex } },
                }
                sectionIndex += 1
                grouped.push(current)
                skip.add(current)
            } else {
                // muted content that's neither shape (multi-paragraph, code block…) —
                // tag the directive itself as one section, keep its children as-is.
                const data = (child.data as Record<string, unknown>) || (child.data = {})
                data.hName = "arcsection"
                data.hProperties = { index: sectionIndex }
                sectionIndex += 1
                current = null
                grouped.push(child)
                skip.add(child)
            }
        } else if (isLeadBoldParagraph(child as Parameters<typeof isLeadBoldParagraph>[0])) {
            const data = (child.data as Record<string, unknown>) || (child.data = {})
            data.hName = "arcsection"
            data.hProperties = { index: sectionIndex }
            sectionIndex += 1
            current = null
            grouped.push(child)
            skip.add(child)
        } else if (current) {
            current.children.push(child)
        } else {
            grouped.push(child)
        }
    }
    node.children = grouped
    for (const child of node.children) {
        if (skip.has(child)) {
            continue
        }
        groupArcSections(child as Parameters<typeof groupArcSections>[0])
    }
}

/** remark transformer: box each Interview Arc label + its following body into one `arcsection`. */
const remarkArcSections = () => (tree: unknown): void => {
    groupArcSections(tree as Parameters<typeof groupArcSections>[0])
}

/**
 * Module-level constant — NOT recreated every render. If `remarkPlugins={[...]}` were inline, each
 * MarkdownContent re-render would hand ReactMarkdown a new array → re-parse the whole markdown.
 */
const REMARK_PLUGINS = [remarkGfm, remarkDirective, remarkMuted, remarkTab, remarkChip, remarkAccordion]
// Opt-in variant (flashcard/mock-interview answers, see `arcSections` prop) — same
// stable module-level array so ReactMarkdown never sees a fresh array identity.
const REMARK_PLUGINS_ARC = [...REMARK_PLUGINS, remarkArcSections]

// Matches each ```mermaid fence and the figure caption paragraph that follows it.
// Group 1 = diagram source; group 2 = the first non-blank line after the fence.
const MERMAID_CAPTION_REGEX = /```mermaid[ \t]*\r?\n([\s\S]*?)\r?\n```[ \t]*\r?\n+[ \t]*([^\r\n]+)/g

/**
 * Cuts off a trailing ```mermaid fence that hasn't been closed yet — markdown fed in
 * progressively (the mock-interview typewriter reveal, an AI stream) walks THROUGH every
 * partial length of the diagram source one tick at a time, and `mermaid.render()` throws
 * "Syntax error in text" for every one of those incomplete snapshots. Since a reveal only
 * ever GROWS the text, at most the LAST fence can be unterminated — any earlier one
 * already has content (and therefore its closing fence) after it.
 * @param markdown - Raw markdown source, possibly mid-reveal.
 * @returns `markdown` unchanged, or truncated right before an unterminated trailing mermaid fence.
 */
export const holdBackIncompleteMermaidFence = (markdown: string): string => {
    const lines = markdown.split("\n")
    let lastOpenLine = -1
    for (let i = 0; i < lines.length; i++) {
        if (/^```mermaid[ \t]*$/.test(lines[i].trimEnd())) {
            lastOpenLine = i
        }
    }
    if (lastOpenLine === -1) {
        return markdown
    }
    const isClosed = lines.slice(lastOpenLine + 1).some((line) => line.trim() === "```")
    return isClosed ? markdown : lines.slice(0, lastOpenLine).join("\n").trimEnd()
}

/**
 * Scans markdown for mermaid blocks and pairs each with the caption paragraph that
 * immediately follows it (a figure-caption line, Vietnamese or English), keyed by trimmed source.
 * @param markdown - Raw markdown source.
 * @returns Caption text keyed by trimmed mermaid source.
 */
export const extractMermaidCaptions = (markdown: string): Record<string, string> => {
    const captions: Record<string, string> = {}
    // Reset lastIndex defensively since the regex is module-scoped + global.
    MERMAID_CAPTION_REGEX.lastIndex = 0
    for (let match = MERMAID_CAPTION_REGEX.exec(markdown); match; match = MERMAID_CAPTION_REGEX.exec(markdown)) {
        const code = match[1].trim()
        // Strip surrounding italic markers authors wrap captions in (*...*).
        const caption = match[2].trim().replace(/^\*+|\*+$/g, "").trim()
        // Only adopt lines that read as figure captions, not following prose.
        if (/^(Hình|Figure)\b/i.test(caption)) { // vn-ok: matches the VI figure word in lesson prose
            captions[code] = caption
        }
    }
    return captions
}

/**
 * Removes each mermaid figure-caption paragraph ("Figure N: …", either language) from the source
 * so it isn't rendered twice — the diagram now shows it as a real `<figcaption>`. Non-caption
 * paragraphs after a fence are left intact.
 * @param markdown - Raw markdown source.
 * @returns Markdown with figure-caption paragraphs stripped.
 */
const stripMermaidCaptions = (markdown: string): string => {
    MERMAID_CAPTION_REGEX.lastIndex = 0
    return markdown.replace(MERMAID_CAPTION_REGEX, (match: string, _code: string, caption: string) => {
        const clean = caption.trim().replace(/^\*+|\*+$/g, "").trim()
        if (/^(Hình|Figure)\b/i.test(clean)) { // vn-ok: matches the VI figure word in lesson prose
            // keep the fence + the blank line(s) after it, drop only the caption text
            return match.slice(0, match.lastIndexOf(caption))
        }
        return match
    })
}

/**
 * Strips Anki-style cloze markers `{{cN::term}}` (or `{{cN::term::distractorA,
 * distractorB}}` — the optional trailing group is the quiz's curated
 * confuser set, dropped entirely here) down to just the term, so a flashcard
 * answer renders cleanly everywhere (reviewer / due / quiz full answer). The
 * `cN::` prefix makes the pattern distinctive — it never collides with
 * template braces like `{{ user.name }}` in lesson code samples.
 * @param markdown - Raw markdown that may carry cloze markers.
 */
const stripClozeMarkers = (markdown: string): string =>
    markdown.replace(/\{\{c\d+::([\s\S]*?)(?:::[\s\S]*?)?\}\}/g, "$1")

/** Intrinsic type scale on the prose root (independent of {@link MarkdownContentProps.reading}). */
export type MarkdownDensity = "default" | "compact" | "caption"

/** Foreground colour role on the prose root. */
export type MarkdownTone = "default" | "muted"

/** Whether paragraphs keep document rhythm or sit flush as an embedded passenger. */
export type MarkdownFlow = "document" | "embedded"

/** Italic emphasis on the whole prose root. */
export type MarkdownEmphasis = "normal" | "italic"

/** Clamp each paragraph to this many visible lines (preview / list snip). */
export type MarkdownPreviewLines = 1 | 2

/** Props for {@link _MarkdownContent} — presentational; the renderer map already resolved. */
export interface MarkdownContentProps {
    /** Markdown source string. */
    markdown: string
    /**
     * Reading-grade typography for full lesson articles: 16px body, looser line
     * rhythm and a stronger heading ladder. Off by default (compact scale used in
     * cards, chat, flashcards and modals).
     */
    reading?: boolean
    /**
     * Boxes each Interview Arc label (`:::muted` / standalone-bold paragraph) together
     * with its following body into one collapsible `arcsection` — see `map.tsx`.
     * Opt-in (default off) so lesson/challenge content using the same `:::muted`
     * shape for unrelated callouts (e.g. "Input"/"Output") is unaffected. Only the
     * flashcard/mock-interview answer (FlipCard back face) turns this on.
     */
    arcSections?: boolean
    /** Intrinsic type scale on the prose root. Defaults to `"default"`. */
    density?: MarkdownDensity
    /** Foreground colour role on the prose root. Defaults to `"default"`. */
    tone?: MarkdownTone
    /** Document rhythm vs flush embedded paragraphs. Defaults to `"document"`. */
    flow?: MarkdownFlow
    /** Italic emphasis on the prose root. Defaults to `"normal"`. */
    emphasis?: MarkdownEmphasis
    /** Clamp each paragraph to 1 or 2 visible lines (omit for no clamp). */
    previewLines?: MarkdownPreviewLines
    /** The element-renderer map, already resolved (theme + i18n baked in). */
    components: Components
}

/**
 * Renders markdown with GFM and shared typography aligned with the app theme.
 *
 * Presentational: the connected half resolves the active theme/translator into
 * the `components` renderer map; this file only runs the pure markdown-source
 * transforms (hold-back-incomplete-fence, strip captions/cloze) and renders
 * `ReactMarkdown`. Marked `"use client"` via the connected half.
 * @see Story: .storybook/stories/blocks/rendering/MarkdownContent/MarkdownContent.stories
 * @param props - {@link MarkdownContentProps}
 */
export const _MarkdownContent = ({
    markdown,
    reading = false,
    arcSections = false,
    density = "default",
    tone = "default",
    flow = "document",
    emphasis = "normal",
    previewLines,
    components,
}: MarkdownContentProps) => {
    // hold back an unterminated trailing mermaid fence FIRST — markdown streamed in
    // progressively (typewriter reveal, AI token stream) walks through every partial
    // length of a diagram's source, and parsing those mid-fence snapshots is what
    // throws mermaid's "Syntax error in text". The rest of the pipeline only ever
    // sees a diagram once its fence is fully closed.
    const stableMarkdown = useMemo(() => holdBackIncompleteMermaidFence(markdown), [markdown])
    // Strip mermaid figure-captions (rendered as `<figcaption>`) + cloze markers (rendered plain).
    const renderedMarkdown = useMemo(
        () => stripClozeMarkers(stripMermaidCaptions(stableMarkdown)),
        [stableMarkdown],
    )
    return (
        <div
            className={cn(
                "min-w-0 text-foreground",
                // Reading lessons: NO uniform space-y — each block renderer carries its own
                // asymmetric margin (more above headings than below) for a real section rhythm.
                // Compact (cards / chat / flashcards) keeps the tight uniform rhythm.
                reading
                    ? "text-base leading-7 [&>*:first-child]:mt-0 [&>*:last-child]:mb-0"
                    : "space-y-2 text-sm leading-relaxed",
                // Presentation axes (contract D) — mirror composites/viewers/MarkdownContent.
                density === "compact" && "text-sm",
                density === "caption" && "text-xs",
                tone === "muted" && "text-muted",
                flow === "embedded" && "[&_p]:m-0",
                emphasis === "italic" && "italic",
                previewLines === 1 && "[&_p]:line-clamp-1",
                previewLines === 2 && "[&_p]:line-clamp-2",
            )}
        >
            <ReactMarkdown
                remarkPlugins={arcSections ? REMARK_PLUGINS_ARC : REMARK_PLUGINS}
                components={components}
            >
                {renderedMarkdown}
            </ReactMarkdown>
        </div>
    )
}

"use client"

import React, {
    useEffect,
    useRef,
    useState,
} from "react"
import { Page } from "react-pdf"
import { cn } from "@heroui/react"
import { PAGE_ASPECT_FALLBACK } from "../constants"
import type { WithClassNames } from "@/modules/types/base/class-name"

/** Props for {@link PdfViewportPage}. */
export interface PdfViewportPageProps extends WithClassNames<undefined> {
    /** 1-based page index. */
    pageNumber: number
    /** Scroll container ref used as the IntersectionObserver root. */
    scrollRootRef: React.RefObject<HTMLDivElement | null>
    /** Rendered page width (deferred during resize). */
    width: number
    /** When true, mount the canvas immediately (no IntersectionObserver). */
    eager: boolean
}

/**
 * Renders one PDF page once it nears the viewport to avoid painting every page at once.
 *
 * Presentational: uses only UI-local hooks (`useState`/`useRef`/`useEffect`) to lazily
 * mount the page canvas via an IntersectionObserver.
 * @param props - {@link PdfViewportPageProps}
 */
export const PdfViewportPage = (props: PdfViewportPageProps) => {
    const {
        pageNumber,
        scrollRootRef,
        width,
        eager,
        className,
    } = props
    const wrapRef = useRef<HTMLDivElement | null>(null)
    const [showCanvas, setShowCanvas] = useState(eager)
    const placeholderMinH = Math.max(
        160,
        Math.round(width * PAGE_ASPECT_FALLBACK),
    )

    useEffect(() => {
        if (eager) {
            setShowCanvas(true)
            return
        }
        if (showCanvas) {
            return
        }
        const el = wrapRef.current
        if (!el) {
            return
        }
        const root = scrollRootRef.current ?? undefined
        const io = new IntersectionObserver(
            (entries) => {
                const entry = entries[0]
                if (entry?.isIntersecting) {
                    setShowCanvas(true)
                }
            },
            {
                root,
                rootMargin: "100% 0px 120% 0px",
                threshold: 0.01,
            },
        )
        io.observe(el)
        return () => io.disconnect()
    }, [
        eager,
        scrollRootRef,
        showCanvas,
        pageNumber,
    ])

    return (
        <div
            ref={wrapRef}
            className={cn("flex justify-center", className)}
        >
            {
                showCanvas ? (
                    <Page
                        pageNumber={pageNumber}
                        width={width}
                        renderTextLayer={false}
                        renderAnnotationLayer={false}
                    />
                ) : (
                    <div
                        className="w-full max-w-full rounded-medium bg-default-100/30"
                        style={{ minHeight: placeholderMinH }}
                        aria-hidden
                    />
                )
            }
        </div>
    )
}

"use client"

import React, {
    useDeferredValue,
    useEffect,
    useLayoutEffect,
    useMemo,
    useRef,
    useState,
} from "react"
import { Document, pdfjs } from "react-pdf"
import { cn } from "@heroui/react"
import { RESIZE_DEBOUNCE_MS } from "./constants"
import { PdfViewportPage } from "./PdfViewportPage"
import {
    resolvePDFViewHeight,
    type PDFViewHeight,
} from "@/components/composites/_semantic-contracts"

pdfjs.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${pdfjs.version}/build/pdf.worker.min.mjs`

export type { PDFViewHeight }

/** Props for {@link PDFView}. */
export interface PDFViewProps {
    /** Source URL of the PDF file to preview. */
    src: string
    /** Accessible title for the iframe viewer. */
    title: string
    /**
     * Named viewer height. Prefer this over raw height class escapes.
     * @default "document"
     */
    height?: PDFViewHeight
    /** Optional page width for PDF rendering. */
    pageWidth?: number
    /** Render all pages or only first page. */
    showAllPages?: boolean
    /** Allow vertical scroll in viewer container. */
    allowVerticalScroll?: boolean
    /** Auto fit rendered PDF width to container width. */
    fitToContainer?: boolean
}

/**
 * Reusable PDF preview viewer built on react-pdf.
 *
 * Presentational: uses only UI-local hooks (refs, resize/layout effects, deferred width)
 * to size pages to the container; no business logic. Marked `"use client"` for the DOM
 * observers and react-pdf canvas rendering.
 * @param props - {@link PDFViewProps}
 */
export const PDFView = ({
    src,
    title,
    height = "document",
    pageWidth = 840,
    showAllPages = true,
    allowVerticalScroll = false,
    fitToContainer = false,
}: PDFViewProps) => {
    const file = useMemo(() => (src ? src : undefined), [src])
    const [numPages, setNumPages] = useState(0)
    const containerRef = useRef<HTMLDivElement | null>(null)
    const scrollRootRef = useRef<HTMLDivElement | null>(null)
    const [containerWidth, setContainerWidth] = useState(0)
    const computedPageWidth = fitToContainer && containerWidth > 0
        ? Math.max(320, Math.floor(containerWidth) - 24)
        : pageWidth
    const deferredPageWidth = useDeferredValue(computedPageWidth)
    const renderWidth = deferredPageWidth > 0 ? deferredPageWidth : computedPageWidth

    const assignContainerRef = (node: HTMLDivElement | null) => {
        containerRef.current = node
        scrollRootRef.current = node
    }

    useLayoutEffect(() => {
        if (!fitToContainer) {
            return
        }
        const el = containerRef.current
        if (!el) {
            return
        }
        const w = Math.floor(el.getBoundingClientRect().width)
        if (w > 0) {
            setContainerWidth(w)
        }
    }, [
        fitToContainer,
        src,
        height,
    ])

    useEffect(() => {
        if (!fitToContainer) {
            return
        }
        const element = containerRef.current
        if (!element) {
            return
        }
        let timeoutId: NodeJS.Timeout | undefined
        const observer = new ResizeObserver((entries) => {
            const nextWidth = Math.floor(entries[0]?.contentRect.width ?? 0)
            clearTimeout(timeoutId)
            timeoutId = setTimeout(
                () => {
                    setContainerWidth(nextWidth)
                }, RESIZE_DEBOUNCE_MS
            )
        })
        observer.observe(element)
        return () => {
            clearTimeout(timeoutId)
            observer.disconnect()
        }
    }, [
        fitToContainer,
        src,
    ])

    const pageCount = showAllPages ? numPages : Math.min(1, numPages)

    return (
        <div
            ref={assignContainerRef}
            className={cn(
                resolvePDFViewHeight(height),
                "overflow-x-auto bg-surface scrollbar-thin scrollbar-thumb-accent scrollbar-track-surface-secondary",
                allowVerticalScroll ? "overflow-y-auto" : "overflow-y-hidden",
            )}
        >
            {file ? (
                <Document
                    key={src}
                    file={file}
                    loading={<div className="text-sm text-muted">{title}</div>}
                    error={<div className="text-sm text-danger-soft-foreground">Failed to render PDF.</div>}
                    noData={<div className="text-sm text-muted">No PDF selected.</div>}
                    onLoadSuccess={(pdf) => setNumPages(pdf.numPages)}
                >
                    <div className="flex flex-col gap-3">
                        {Array.from({ length: pageCount }, (_, index) => {
                            const pageNumber = index + 1
                            const eager = !showAllPages || pageNumber <= 2
                            return (
                                <PdfViewportPage
                                    key={`pdf-page-${pageNumber}-${src}`}
                                    eager={eager}
                                    pageNumber={pageNumber}
                                    scrollRootRef={scrollRootRef}
                                    width={renderWidth}
                                />
                            )
                        })}
                    </div>
                </Document>
            ) : (
                <div className="text-sm text-muted">No PDF selected.</div>
            )}
        </div>
    )
}

"use client"

import React, { useMemo } from "react"
import {
    Background,
    BackgroundVariant,
    type Edge,
    Handle,
    type Node,
    type NodeProps,
    Position,
    ReactFlow,
    ReactFlowProvider,
} from "@xyflow/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { StackH, StackV } from "@/components/frames/Stack"
import { StatusChip } from "@/components/blocks/chips/StatusChip"

/** React Flow node-type id for {@link RagSourceGraph}'s question node. */
const RAG_SOURCE_GRAPH_QUESTION_NODE_TYPE = "question" as const

/** React Flow node-type id for {@link RagSourceGraph}'s source node. */
const RAG_SOURCE_GRAPH_SOURCE_NODE_TYPE = "source" as const

/** Data carried on the single {@link RAG_SOURCE_GRAPH_QUESTION_NODE_TYPE} node. */
interface RagSourceGraphQuestionNodeData extends Record<string, unknown> {
    /** The visitor's question, shown truncated to ~2 lines. */
    question: string
}

/** Data carried on one {@link RAG_SOURCE_GRAPH_SOURCE_NODE_TYPE} node. */
interface RagSourceGraphSourceNodeData extends Record<string, unknown> {
    /** File path (or synthetic label) the chunk came from — rendered `font-mono`. */
    filePath: string
    /** First line of the chunk's excerpt, truncated. */
    snippetPreview: string
    /** Retrieval score (0-1), when the backend reports one. */
    score?: number
}

/**
 * The question — a single accent-filled node anchored on the left of the
 * canvas, fanning out to every source it grounded the answer in.
 *
 * @param props - React Flow {@link NodeProps} carrying {@link RagSourceGraphQuestionNodeData}.
 */
const RagSourceGraphQuestionNode = ({ data }: NodeProps) => {
    const { question } = data as RagSourceGraphQuestionNodeData
    return (
        <>
            {/* Connection point — required for a CUSTOM node or edges never draw. */}
            <Handle type="target" position={Position.Left} className="!size-2 !border-none !bg-muted" />
            {/* `Box`: the frame tier's escape hatch for a foreign-library mount point (here, an
                `@xyflow/react` custom node) — a plain flex/atom composition can't carry the
                node's own bg/rounded/shadow skin. */}
            <Box className="max-w-[220px] rounded-large bg-accent px-4 py-3 shadow-sm">
                {/* missingVocabulary: `Typography`'s color axis pairs `accent-soft` with a
                    SOFT-tinted surface but has no foreground for text on a SOLID `bg-accent`
                    surface, so the atom can't reproduce `text-accent-foreground` here. Kept as
                    a plain element rather than losing contrast to the atom's default color. */}
                <p className="line-clamp-2 text-sm font-medium text-accent-foreground">{question}</p>
            </Box>
            <Handle type="source" position={Position.Right} className="!size-2 !border-none !bg-muted" />
        </>
    )
}

/**
 * One retrieved source chunk — a small card naming the file it came from, a
 * one-line preview of the matched excerpt, and (when the backend reports one)
 * the retrieval score as a chip.
 *
 * @param props - React Flow {@link NodeProps} carrying {@link RagSourceGraphSourceNodeData}.
 */
const RagSourceGraphSourceNode = ({ data }: NodeProps) => {
    const { filePath, snippetPreview, score } = data as RagSourceGraphSourceNodeData

    // `StatusChip` (block tier) exposes no `classNames`/positioning escape hatch at all — not
    // even the closed `AllowedClassName` set atoms/frames get — so it can no longer be told
    // `shrink-0`. Worked around from the OTHER side of the row instead: `filePath` below takes
    // `min-w-0`/`flex-1`, which lets IT shrink/truncate first and leaves the chip its natural size.
    const filePathRowItems = [
        () => (
            // missingVocabulary: `Typography` has no plain monospace body variant — its
            // `size="code"` wraps HeroUI's `.typography--code`, which pulls in a padded/`bg-default`
            // pill, not a bare `font-mono` run — so the exact `font-mono text-accent-soft-foreground`
            // pairing this file path needs can't be expressed through the atom.
            <span className="min-w-0 flex-1 truncate font-mono text-xs font-medium text-accent-soft-foreground">
                {filePath}
            </span>
        ),
        ...(score != null ? [() => <StatusChip tone="accent">{score.toFixed(2)}</StatusChip>] : []),
    ]

    return (
        <>
            <Handle type="target" position={Position.Left} className="!size-2 !border-none !bg-muted" />
            {/* `Box`: same foreign-library-mount rationale as the question node above. */}
            <Box className="w-[220px] rounded-large border border-default bg-surface px-3 py-2 shadow-sm">
                <StackV
                    gap={2}
                    principle="title-subtitle"
                    explain="Title over supporting line — not label-field, because neither line is a form control label."
                    items={[
                        () => <StackH gap={3} principle="chip-row" justify="between" items={filePathRowItems} explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."/>,
                        () => <Typography size="xs" color="muted" truncate text={snippetPreview} />,
                    ]}
                />
            </Box>
            <Handle type="source" position={Position.Right} className="!size-2 !border-none !bg-muted" />
        </>
    )
}

/** Node type map registered on the canvas. */
const NODE_TYPES = {
    [RAG_SOURCE_GRAPH_QUESTION_NODE_TYPE]: RagSourceGraphQuestionNode,
    [RAG_SOURCE_GRAPH_SOURCE_NODE_TYPE]: RagSourceGraphSourceNode,
}

/** Vertical gap between fanned-out source nodes, in px. */
const SOURCE_ROW_HEIGHT = 110
/** Horizontal offset of the source column from the question node, in px. */
const SOURCE_COLUMN_X = 320

/** One retrieved source chunk, as passed to {@link RagSourceGraph}. */
export interface RagSourceGraphSource {
    /** File path (or synthetic label) the chunk came from. */
    filePath: string
    /** Excerpt of the chunk's content. */
    snippet: string
    /** Retrieval score (0-1), when the backend reports one. */
    score?: number
}

/**
 * Props for the {@link RagSourceGraph} block. Does NOT take `className`
 * (BLOCK-4) — its only caller (`PlaygroundRagWorkspace`) never passed one, so
 * the escape hatch closes outright rather than being renamed to `classNames`.
 */
export interface RagSourceGraphProps {
    /** The question the sources grounded the answer for — shown on the left node. */
    question: string
    /** Retrieved source chunks, fanned out on the right, one node each. */
    sources: Array<RagSourceGraphSource>
}

/**
 * A small `@xyflow/react` graph visualizing WHICH retrieved chunks grounded
 * one RAG answer: a single accent question node on the left, an edge to every
 * source card fanned out on the right (edge label = retrieval score, when
 * present). Mirrors `FlowDiagram`'s self-contained provider/background/fit-view
 * setup, but ships its own two node types instead of a generic labeled card,
 * since a question/source pair has a fixed shape unlike a free-form diagram.
 *
 * Node positions are computed deterministically from the source list's index
 * (question anchored at the vertical center of the fan-out) — no randomness,
 * so the same sources always lay out the same way.
 *
 * @param props - See {@link RagSourceGraphProps}.
 *
 * @see Story: .storybook/stories/blocks/rendering/RagSourceGraph/RagSourceGraph.stories
 */
export const RagSourceGraph = ({ question, sources }: RagSourceGraphProps) => {
    const nodeTypes = useMemo(() => NODE_TYPES, [])

    const { nodes, edges } = useMemo<{ nodes: Array<Node>; edges: Array<Edge> }>(() => {
        const centerY = ((sources.length - 1) * SOURCE_ROW_HEIGHT) / 2

        const questionNode: Node = {
            id: "question",
            type: RAG_SOURCE_GRAPH_QUESTION_NODE_TYPE,
            position: { x: 0, y: centerY },
            data: { question } satisfies RagSourceGraphQuestionNodeData,
        }

        const sourceNodes: Array<Node> = sources.map((source, index) => ({
            id: `source-${index}`,
            type: RAG_SOURCE_GRAPH_SOURCE_NODE_TYPE,
            position: { x: SOURCE_COLUMN_X, y: index * SOURCE_ROW_HEIGHT },
            data: {
                filePath: source.filePath,
                snippetPreview: source.snippet.split("\n")[0] ?? "",
                score: source.score,
            } satisfies RagSourceGraphSourceNodeData,
        }))

        const sourceEdges: Array<Edge> = sources.map((source, index) => ({
            id: `edge-${index}`,
            source: "question",
            target: `source-${index}`,
            label: source.score != null ? source.score.toFixed(2) : undefined,
        }))

        return { nodes: [questionNode, ...sourceNodes], edges: sourceEdges }
    }, [question, sources])

    return (
        // Plain `div` rather than `Box`: this root must self-identify as the BLOCK
        // (`data-tier`/`data-component`), and `Box` hard-codes its own `"frame"`/`"Box"` pair —
        // the same reason the sibling `FlowDiagram` composite's root stays a hand-written `div`.
        <div
            data-tier="block"
            data-component="RagSourceGraph"
            className="h-[300px] w-full overflow-hidden rounded-large border border-default"
        >
            <ReactFlowProvider>
                <ReactFlow
                    className="text-foreground"
                    defaultEdges={edges}
                    defaultNodes={nodes}
                    fitView
                    fitViewOptions={{ padding: 0.2 }}
                    maxZoom={2}
                    minZoom={0.2}
                    nodeTypes={nodeTypes}
                    proOptions={{ hideAttribution: true }}
                >
                    <Background gap={16} variant={BackgroundVariant.Dots} />
                </ReactFlow>
            </ReactFlowProvider>
        </div>
    )
}

import { cn } from "@heroui/react"
import { XIcon } from "@phosphor-icons/react"
import { Typography } from "@/components/atoms/text/Typography"
import { Button, type IconComponent } from "@/components/atoms/buttons/Button"
import { StackH } from "@/components/frames/Stack"

/**
 * ─────────────────────────────────────────────────────────────────────────────
 * STORYBOOK-LOCAL DESIGN SPEC — the target `RemovableToken`. Authored in
 * Storybook (not `src`); synced to `src` later. NO `@/components` imports.
 *
 * Grounded in the hand-rolled "picked company" row in
 * `CompanySection` (`src/components/features/careers/Jobs/JobPostForm/CompanySection/index.tsx`):
 * a bordered `rounded-2xl` flex row — a label on the left, a tertiary
 * `Button` (× icon + "Change" text) on the right that clears the pick. This
 * composite generalises that ONE hand-rolled row into a reusable
 * selected-item token: any label/icon in, an optional remove (×) and/or
 * edit ("Change"-style) affordance out.
 * ─────────────────────────────────────────────────────────────────────────────
 */

/** Props for the {@link RemovableToken} composite. */
export interface RemovableTokenProps {
    /** Token label content — text the composite wraps itself (in `Typography`). */
    label: string
    /**
     * Optional LEADING glyph before the label, passed as a COMPONENT reference
     * (e.g. `icon={FolderIcon}`), never JSX — the composite renders it at its own
     * scale (`size-4`) and, being a reference rather than an already-called node,
     * can still call it during `isSkeleton` (unlike a frozen element).
     */
    icon?: IconComponent
    /**
     * Renders a trailing edit affordance — a small tertiary `Button` (× icon +
     * {@link RemovableTokenProps.editLabel}), mirroring the ground-truth
     * "Change" button that clears a picked company so the user can re-search.
     * Use this when removing the token means "go pick a different one", not
     * "delete it".
     */
    onEdit?: () => void
    /** Label for the edit affordance's button text. Defaults to "Change". */
    editLabel?: string
    /**
     * Renders a trailing COMPACT close (×) — click it to remove the token
     * outright (no re-pick flow). Own compact scale (size-6 hit, size-4
     * glyph), like a chip's cancel-×, not the button-scale edit affordance.
     */
    onRemove?: () => void
    /** Accessible label for the remove (×) button. Falls back to "Remove". */
    removeLabel?: string
    /** Disables both affordances and dims the token. */
    isDisabled?: boolean
    /** `true` → render the skeleton mirror (row frame + placeholder bars). */
    isSkeleton?: boolean
}

/**
 * Generic selected-item token: a bordered `rounded-2xl` row holding an
 * optional leading icon + label, with an optional trailing remove (×) and/or
 * edit ("Change"-style) affordance. Compact — one line, no wrapping content.
 * Presentational; the only callbacks it takes are the two trailing
 * affordances.
 *
 * @param props - {@link RemovableTokenProps}
 */
/** Source-level tier metadata — see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "RemovableToken" } as const

/** A bordered row token showing a label with optional remove (x) and edit affordances. */
export const RemovableToken = ({
    label,
    icon: Icon,
    onEdit,
    editLabel = "Change",
    onRemove,
    removeLabel = "Remove",
    isDisabled = false,
    
    isSkeleton = false}: RemovableTokenProps) => {
    // One render path: the row's own frame stays identical whether loading or not;
    // only the trailing affordance's CONTENT differs (a shimmer pill vs the real
    // edit/remove controls) — `Button`/`Typography` each draw their own shimmer,
    // this composite only decides which parts show and how many (COMPOSITE-10).
    const trailing = isSkeleton ? (
        <span className="shrink-0"><Button isSkeleton size="sm" /></span>
    ) : onEdit || onRemove ? (
        <StackH
            gap={3}
            classNames={["shrink-0"]}
            items={[
                ...(onEdit
                    ? [() => (
                        <Button variant="tertiary" size="sm" isDisabled={isDisabled} onPress={onEdit} prefixIcon={XIcon} label={editLabel} />
                    )]
                    : []),
                ...(onRemove
                    ? [() => (
                        // Compact chip-scale close × (NOT the button-scale edit
                        // affordance above) — a real <button> for a11y.
                        <button
                            type="button"
                            aria-label={removeLabel}
                            disabled={isDisabled}
                            onClick={onRemove}
                            className="inline-flex size-6 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted outline-none transition hover:bg-default hover:text-foreground focus-visible:ring-2 focus-visible:ring-accent disabled:cursor-not-allowed [&_svg]:size-4"
                        >
                            <XIcon aria-hidden focusable="false" />
                        </button>
                    )]
                    : []),
            ]}
        />
    ) : null

    return (
        <div
            aria-disabled={isDisabled}
            className={cn(
                "flex items-center justify-between gap-3 rounded-2xl border border-default px-3 py-3",
                isDisabled && "opacity-50")}
            data-tier="composite"
            data-component="RemovableToken"
            data-principle="cell-pad"
        >
            <StackH
                gap={3}
                classNames={["min-w-0"]}
                items={[
                    ...(Icon
                        ? [() => (
                            // COMPOSITE owns the size (§4) — the atom's own scale, not the
                            // caller's. A component reference can still be called during
                            // `isSkeleton` (it's static chrome, not loaded data), so it
                            // always renders — no shimmer needed for it either way.
                            <span aria-hidden className="inline-flex shrink-0 [&_svg]:size-4">
                                <Icon />
                            </span>
                        )]
                        : []),
                    () => (
                        <Typography
                            size="sm"
                            weight="medium"
                            truncate
                            isSkeleton={isSkeleton}
                            text={label}
                        />
                    ),
                ]}
            />
            {trailing}
        </div>
    )
}

import { InputTextarea } from "@/components/atoms/forms"
import React, { useCallback, useState } from "react"
import { SealCheckIcon } from "@phosphor-icons/react"
import { AsyncContentEmpty, AsyncContentError } from "@/components/composites/async/AsyncContent"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"
import { Button } from "@/components/atoms/buttons/Button"

import { Typography } from "@/components/atoms/text/Typography"
import { Box } from "@/components/frames/Box"
import { ScrollArea } from "@/components/frames/ScrollArea"
import { StackH, StackV } from "@/components/frames/Stack"
import { ChatBubble } from "@/components/blocks/feed/ChatBubble"
import { UserCell } from "@/components/composites/lists/UserCell"
import { Skeleton } from "@/components/blocks/skeleton/Skeleton"
import type { ChatMessageNode } from "@/modules/api/graphql/queries/types/chat"

/** How many placeholder rows the co-located skeleton shows for the message list. */
const SKELETON_ROW_COUNT = 3

/** All display text, already localized by the connected `ChatPane`; a story passes i18n keys. */
export interface ChatPaneLabels {
    /** Empty-state title — no messages yet. */
    empty: string
    /** Error-state title — the message list failed to load. */
    error: string
    /** Retry-button label paired with {@link ChatPaneProps.onRetry}. */
    retry: string
    /** Composer placeholder / accessible name. */
    placeholder: string
    /** Send-button label. */
    send: string
}

/** Props for {@link _ChatPane} — presentational; all data resolved, no fetch/store/i18n. */
export interface ChatPaneProps {
    /** First load, nothing in hand → the message list shimmers in place (co-located). Owned by the connected file. */
    isSkeleton?: boolean
    /** Settled with zero messages → the empty message. */
    isEmpty?: boolean
    /** Truthy → the error message (beats loading + empty). The connected file passes its settled fetch error. */
    error?: unknown
    /** Retry handler for the error branch. */
    onRetry?: () => void
    /** Messages, oldest→newest, already resolved by the connected file. */
    messages?: Array<ChatMessageNode>
    /** `true` while a send is in flight — locks the send button and shows its spinner. */
    isSending?: boolean
    /** Sends the composed body; resolves `true` on success (the composer clears itself), `false` otherwise. */
    onSend: (body: string) => Promise<boolean>
    /** Already-translated copy — see {@link ChatPaneLabels}. */
    labels: ChatPaneLabels
}

/**
 * `_ChatPane` — the presentational half of {@link import(".").ChatPane}: one
 * chat conversation's message list + composer. Three states in the fixed
 * order error → empty → content (`loading-and-skeleton.md`): `error` falls
 * to the shared `AsyncContentError` frame, a settled `isEmpty` to
 * `AsyncContentEmpty`, and otherwise the message list renders with
 * `isSkeleton` threaded down to every leaf that supports it — placeholder
 * rows keep the SAME `ChatBubble` shape as the loaded state, alternating
 * `isMine` the way real messages do so the sender row shows/hides in the
 * same pattern. `UserCell` itself has no `isSkeleton`, so that one sender
 * row is mirrored in place with `Skeleton.UserCell` instead (still
 * co-located, not a parallel tree). Only the message-list zone branches —
 * the composer stays mounted underneath regardless, so a member can still
 * write while the history is loading or failed to load. See
 * `tiers/split.md` — the connected `index.tsx` owns the fetch, the socket
 * subscription, and i18n.
 *
 * @param props - {@link ChatPaneProps}
 */
export const _ChatPane = ({
    isSkeleton = false,
    isEmpty = false,
    error,
    onRetry,
    messages = [],
    isSending = false,
    onSend,
    labels,
}: ChatPaneProps) => {
    const [body, setBody] = useState("")

    /** Trim + guard, hand off to the connected sender, clear the composer on success. */
    const onSendPress = useCallback(async () => {
        const trimmed = body.trim()
        if (!trimmed) {
            return
        }
        const ok = await onSend(trimmed)
        if (ok) {
            setBody("")
        }
    }, [body, onSend])

    // Row shape shared by both states: while shimmering, placeholder rows alternate
    // `isMine` the same way real messages do, so the sender row (UserCell) shows/hides
    // in the SAME pattern the loaded list will settle into — nothing collapses or jumps.
    const rows = isSkeleton
        ? Array.from({ length: SKELETON_ROW_COUNT }, (_unused, index) => ({
            isMine: index % 2 === 1,
            body: undefined as string | undefined,
            author: undefined as ChatMessageNode["author"] | undefined,
            isFounderAuthor: false,
        }))
        : messages.map((message) => ({
            isMine: message.isMine,
            body: message.body as string | undefined,
            author: message.author as ChatMessageNode["author"] | undefined,
            isFounderAuthor: message.isFounderAuthor,
        }))

    const messageRows: Array<ComponentTypeWithSkeleton> = rows.map((row) => () => (
        <StackV gap={2} items={[
            ...(!row.isMine ? [() => (
                isSkeleton || !row.author ? (
                    <Skeleton.UserCell withHandle={false} />
                ) : (
                    <UserCell
                        username={row.author!.username}
                        displayName={row.author!.displayName ?? undefined}
                        avatar={row.author!.avatar ?? undefined}
                        size="sm"
                        trailing={row.isFounderAuthor
                            ? () => <SealCheckIcon weight="fill" className="size-3.5 shrink-0 text-accent-soft-foreground" />
                            : undefined}
                    />
                )
            )] : []),
            () => (
                <ChatBubble role={row.isMine ? "user" : "assistant"}>
                    <Typography size="sm" text={row.body ?? ""} isSkeleton={isSkeleton} />
                </ChatBubble>
            ),
        ]} />
    ))

    return (
        <StackV
            gap={4}
            principle="content-row"
            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
            identity={{ tier: "block", component: "ChatPane" }}
            items={[
                () => (
                    error ? (
                        <AsyncContentError title={labels.error} onRetry={onRetry} retryLabel={labels.retry} />
                    ) : !isSkeleton && isEmpty ? (
                        <AsyncContentEmpty title={labels.empty} />
                    ) : (
                        // NEW-VOCABULARY GAP: no frame owns "cap this region's height and scroll
                        // it locally" — `ScrollArea`'s `classNames` is a closed, positioning-only
                        // enum (no height values) — so the height cap goes through `Box` (the
                        // sanctioned raw-appearance escape hatch), same shape as `FollowListModal`.
                        <Box className="max-h-[60vh]">
                            <ScrollArea axis="y" body={() => <StackV gap={4} isSkeleton={isSkeleton} items={messageRows} />} />
                        </Box>
                    )
                ),
                () => (
                    <StackV gap={3} principle="flex-action"
                        explain="Groups action controls on one horizontal peer row so they share a single hit baseline."
                        items={[
                            () => (
                                <InputTextarea
                                    variant="secondary"
                                    rows={2}
                                    value={body}
                                    onValueChange={setBody}
                                    placeholder={labels.placeholder}
                                    ariaLabel={labels.placeholder}
                                />
                            ),
                            () => (
                                <StackH gap={1} principle="name-handle"
                                    explain="Display name with handle — not title-subtitle, because the second line is an identity handle rather than a subtitle."
                                    justify="end" items={[
                                        () => (
                                            <Button
                                                variant="primary"
                                                size="sm"
                                                label={labels.send}
                                                isPending={isSending}
                                                isDisabled={!body.trim()}
                                                onPress={() => void onSendPress()}
                                            />
                                        ),
                                    ]} />
                            ),
                        ]} />
                ),
            ]}
        />
    )
}

"use client"

import React, { useMemo, useState } from "react"
import { Button } from "@heroui/react"
import { UsersThreeIcon } from "@phosphor-icons/react"
import type { Key } from "react"
import { useLocale, useTranslations } from "next-intl"
import { useRouter } from "next/navigation"
import { ChatPane } from "./ChatPane"
import { EmptyState } from "@/components/composites/feedback/EmptyState"
import { PageContainer } from "@/components/blocks/layout/PageContainer"
import { PageHeader } from "@/components/blocks/layout/PageHeader"
import { TabsCard } from "@/components/blocks/navigation/TabsCard"
import { useAuthenticationOverlayState } from "@/hooks/zustand/overlay/hooks"
import { useQueryCommunityChatConversationSwr } from "@/hooks/swr/api/graphql/queries/useQueryCommunityChatConversationSwr"
import { useQueryMyFounderConversationSwr } from "@/hooks/swr/api/graphql/queries/useQueryMyFounderConversationSwr"
import { useAppSelector } from "@/redux/hooks"
import { pathConfig } from "@/resources/path"
import { StackV } from "@/components/frames/Stack"

/** Which conversation the chat surface is showing. */
type ChatTab = "community" | "founder"

/**
 * Community chat surface: a toggle between the global community room and the
 * private founder DM, with the active conversation's message pane below. Member-
 * only — signed-out users see a prompt; the server enforces the membership gate.
 */
export const CommunityChatPage = () => {
    const t = useTranslations()
    const locale = useLocale()
    const router = useRouter()
    const authenticated = useAppSelector((state) => state.keycloak.authenticated)
    const authentication = useAuthenticationOverlayState()
    const [tab, setTab] = useState<ChatTab>("community")

    const communityConversationSwr = useQueryCommunityChatConversationSwr()
    const founderConversationSwr = useQueryMyFounderConversationSwr()

    // the SWR handle for the active tab — chat reads are member-only, so a
    // signed-in non-member either errors (membership gate) or resolves to null.
    const activeConversationSwr = tab === "community"
        ? communityConversationSwr
        : founderConversationSwr

    // the conversation id for the active tab (undefined until resolved)
    const conversationId = activeConversationSwr.data?.id
    // still resolving: only the initial load, before either an id or a terminal
    // (error / null) is known — this is what the skeleton is allowed to cover.
    const isResolving = activeConversationSwr.isLoading && !activeConversationSwr.data
    // the query settled but yielded no conversation for the active tab: the
    // membership gate rejected a signed-in non-member (or the read failed).
    const membersOnly = !isResolving && !conversationId

    const tabs = useMemo(
        () => [
            { key: "community", label: t("community.chat.communityRoom") },
            { key: "founder", label: t("community.chat.founderDm") },
        ],
        [t],
    )

    return (
        <PageContainer>
            <StackV gap={6} principle="block-boundary"
                explain="Block-to-block spacing — not group-boundary, because this separates major blocks rather than nested section groups."
                items={[
                    () => (
                        <PageHeader
                            title={t("community.chat.title")}
                            description={t("community.chat.description")}
                        />
                    ),
                    () => (authenticated ? (
                        <StackV gap={4} principle="content-row"
                            explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                            items={[
                                () => (
                                    <TabsCard
                                        leftTabs={{
                                            items: tabs,
                                            selectedKey: tab,
                                            ariaLabel: t("community.chat.tabsAria"),
                                            onSelectionChange: (key: Key) => setTab(String(key) as ChatTab),
                                        }}
                                    />
                                ),
                                () => (conversationId ? (
                                    <ChatPane key={conversationId} conversationId={conversationId} />
                                ) : membersOnly ? (
                                // Signed-in but the membership gate rejected this read (or it
                                // failed): a non-member must not sit on a perpetual skeleton —
                                // surface a members-only terminal with an upsell to membership.
                                    <EmptyState
                                        icon={UsersThreeIcon}
                                        title={t("community.chat.membersOnly")}
                                        description={t("community.chat.membersOnlyDescription")}
                                        action={() => (
                                            <Button
                                                variant="primary"
                                                size="sm"
                                                onPress={() => router.push(
                                                    pathConfig().locale(locale).profile().membership().build(),
                                                )}
                                            >
                                                {t("community.chat.viewMembership")}
                                            </Button>
                                        )}
                                    />
                                ) : (
                                // 2026-07-12: was a bare "loading…" caption while the active
                                // conversation id resolves — mirror the real pane's shape
                                // (message list + composer) so the tab switch/first load
                                // doesn't jump into a differently-shaped panel afterward.
                                    <ChatPane />
                                )),
                            ]} />
                    ) : (
                        <EmptyState
                            title={t("community.chat.signInRequired")}
                            action={() => (
                                <Button
                                    variant="primary"
                                    size="sm"
                                    onPress={() => authentication.open()}
                                >
                                    {t("nav.signIn")}
                                </Button>
                            )}
                        />
                    )),
                ]} />
        </PageContainer>
    )
}

